package com.delivery.platform.delivery.application;import com.delivery.platform.common.ApiException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;@Service public class DeliveryCoverageService{private final JdbcClient db;public DeliveryCoverageService(JdbcClient db){this.db=db;}public record Quote(boolean eligible,UUID zoneId,BigDecimal distanceKm,int estimatedMinutes,BigDecimal deliveryFee,String currency,BigDecimal minimumOrderAmount,String reasonCode,String message){}public Quote quote(UUID tenant,UUID customer,UUID merchant,UUID branch,UUID address,BigDecimal subtotal){String district=db.sql("select district from delivery_addresses where id=:a and tenant_id=:t and customer_id=:u and active").param("a",address).param("t",tenant).param("u",customer).query(String.class).optional().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"ADDRESS_NOT_FOUND","Dirección no encontrada"));var zone=db.sql("select z.id,z.minimum_order_amount,z.base_delivery_fee,z.currency,z.estimated_minutes,coalesce(r.base_fee,z.base_delivery_fee) base_fee,coalesce(r.fee_per_km,0) fee_km,r.minimum_fee,r.maximum_fee,r.free_delivery_threshold from delivery_zones z left join lateral(select * from delivery_rates where delivery_zone_id=z.id and active order by created_at desc limit 1)r on true where z.tenant_id=:t and z.merchant_id=:m and (z.branch_id is null or z.branch_id=:b) and z.active and lower(z.areas) like lower('%'||:d||'%') order by (z.branch_id is not null) desc limit 1").param("t",tenant).param("m",merchant).param("b",branch).param("d",district==null?"":district).query((x,n)->new Object[]{x.getObject("id",UUID.class),x.getBigDecimal("minimum_order_amount"),x.getBigDecimal("base_fee"),x.getBigDecimal("fee_km"),x.getBigDecimal("minimum_fee"),x.getBigDecimal("maximum_fee"),x.getBigDecimal("free_delivery_threshold"),x.getString("currency"),x.getInt("estimated_minutes")}).optional();if(zone.isEmpty())return new Quote(false,null,null,0,null,null,null,"DELIVERY_OUT_OF_COVERAGE","Dirección fuera de cobertura");Object[]z=zone.get();BigDecimal min=(BigDecimal)z[1];if(subtotal.compareTo(min)<0)return new Quote(false,(UUID)z[0],null,(int)z[8],null,(String)z[7],min,"DELIVERY_MINIMUM_NOT_REACHED","No alcanza el pedido mínimo");BigDecimal distance=new BigDecimal("3.00"),fee=((BigDecimal)z[2]).add(distance.multiply((BigDecimal)z[3]));if(z[4]!=null)fee=fee.max((BigDecimal)z[4]);if(z[5]!=null)fee=fee.min((BigDecimal)z[5]);if(z[6]!=null&&subtotal.compareTo((BigDecimal)z[6])>=0)fee=BigDecimal.ZERO;return new Quote(true,(UUID)z[0],distance,(int)z[8],fee.setScale(2,RoundingMode.HALF_UP),(String)z[7],min,null,"Cobertura disponible");}}
